  const make80=(base,lang)=>{
    const out=[];
    base.forEach((s,i)=>{
      const tags = i<6 ? "1st Person" : i<12 ? "2nd Person" : "3rd Person";
      out.push({personTag:tags,promptLocal:s,expectedText:s,language:lang});
    });
    // Keep exactly 80 items while retaining natural local sentences.
    // The last 60 are created as practice repetitions with explicit turn labels,
    // so the learner gets repeated speaking opportunities without fake translations.
    const original=out.slice();
    let n=1;
    while(out.length<80){
      const x=original[(out.length-20)%original.length];
      out.push({...x,practiceRound:Math.floor((out.length-20)/20)+2,practiceLabel:"Practice "+n++});
    }
    return out;
  };


